20	// It attaches the bearer token to all outgoing requests via the Authorization header.
21	type Client struct {
22		httpClient *http.Client
23		baseURL    string
24	
25		// authTokensPath is the base path for the auth-tokens management
26		// endpoints (list / revoke). Set via WithAuthTokensPath when the
27		// client targets the auth host. Empty for data-API-only clients;
28		// auth-tokens methods error out if called against an empty path.
