40	//	c := api.NewClientWithBaseURL(token, base).WithAuthTokensPath(p)
41	func (c *Client) WithAuthTokensPath(path string) *Client {
42		c.authTokensPath = path
43		return c
44	}
45	
46	// NewClient creates a new authenticated API client with an explicit bearer
47	// token, targeting the data API base URL (BaseURL()).
48	func NewClient(token string) *Client {
49		return NewClientWithBaseURL(token, BaseURL())
50	}
51	
52	// NewClientWithBaseURL creates a new authenticated API client targeting an
53	// explicit base URL. Use this for endpoints that live on the auth host (e.g.
54	// auth-token management) when ENTIRE_AUTH_BASE_URL splits the auth origin
55	// from the data API origin.
56	func NewClientWithBaseURL(token, baseURL string) *Client {
57		return &Client{
58			httpClient: &http.Client{
59				Transport: &bearerTransport{
60					token: token,
61					base:  http.DefaultTransport,
62				},
63			},
64			baseURL: baseURL,
65		}
