68	// bearerTransport is an http.RoundTripper that injects the Authorization header.
69	//
70	// When token is empty, the Authorization header is omitted (rather than sent
71	// as a malformed "Authorization: Bearer "). This supports endpoints like
72	// recap that deliberately want the unauthenticated request to reach the
73	// server so it can return a typed 401 — callers that want a local fast-fail
74	// for missing auth should check ErrNotLoggedIn at construction time, not
75	// rely on the transport.
76	type bearerTransport struct {
77		token string
78		base  http.RoundTripper
