81	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
82		// Clone the request to avoid mutating the caller's request.
83		r := req.Clone(req.Context())
84		if t.token != "" {
85			r.Header.Set("Authorization", "Bearer "+t.token)
86		}
87		r.Header.Set("User-Agent", userAgent)
88		if r.Header.Get("Accept") == "" {
89			r.Header.Set("Accept", "application/json")
90		}
91		resp, err := t.base.RoundTrip(r)
92		if err != nil {
