104	// headers (e.g. Accept: text/event-stream, Last-Event-ID) and returns the
105	// response with the body still open. Callers are responsible for reading and
106	// closing resp.Body. Intended for streaming endpoints such as Server-Sent
107	// Events; for normal JSON requests use Get.
108	func (c *Client) GetStream(ctx context.Context, path string, headers http.Header) (*http.Response, error) {
