139	func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
140		var reader io.Reader
141		if body != nil {
142			data, err := json.Marshal(body)
143			if err != nil {
144				return nil, fmt.Errorf("marshal request body: %w", err)
145			}
146			reader = bytes.NewReader(data)
147		}
148		return c.do(ctx, http.MethodPatch, path, reader, nil)
149	}
150	
151	// Delete sends an authenticated DELETE request to the given API-relative path.
152	func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
153		return c.do(ctx, http.MethodDelete, path, nil, nil)
154	}
155	
156	func (c *Client) do(ctx context.Context, method, path string, body io.Reader, headers http.Header) (*http.Response, error) {
157		endpoint, err := ResolveURLFromBase(c.baseURL, path)
158		if err != nil {
159			return nil, fmt.Errorf("resolve URL %s: %w", path, err)
160		}
161	
162		req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
163		if err != nil {
164			return nil, fmt.Errorf("create request: %w", err)
165		}
166	
167		for k, vs := range headers {
168			for _, v := range vs {
169				req.Header.Add(k, v)
170			}
171		}
172	
173		if body != nil {
174			req.Header.Set("Content-Type", "application/json")
175		}
176	
177		resp, err := c.httpClient.Do(req)
178		if err != nil {
179			return nil, fmt.Errorf("%s %s: %w", method, path, err)
180		}
181		return resp, nil
182	}
183	
184	// DecodeJSON reads the response body and decodes it into dest.
185	// It limits the body size to protect against unbounded reads.
186	// The caller is responsible for closing resp.Body.
187	func DecodeJSON(resp *http.Response, dest any) error {
188		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
189		if err != nil {
190			return fmt.Errorf("read response body: %w", err)
191		}
192	
193		if err := json.Unmarshal(body, dest); err != nil {
194			return fmt.Errorf("decode JSON response: %w", err)
195		}
196	
197		return nil
198	}
199	
200	// ErrorResponse represents a standard API error response. Older endpoints
201	// return {"error":"message"}; newer endpoints return
202	// {"error":{"code":"...","message":"...",...}}.
203	type ErrorResponse struct {
204		Error any `json:"error"`
205	}
206	
207	// Message extracts the human-readable error message from either envelope shape.
208	func (e ErrorResponse) Message() string {
209		switch v := e.Error.(type) {
210		case string:
211			return strings.TrimSpace(v)
212		case map[string]any:
213			if message, ok := v["message"].(string); ok && strings.TrimSpace(message) != "" {
214				return strings.TrimSpace(message)
215			}
216			if code, ok := v["code"].(string); ok && strings.TrimSpace(code) != "" {
217				return strings.TrimSpace(code)
218			}
219		}
220		return ""
221	}
222	
223	// HTTPError is returned by CheckResponse for non-2xx responses. Callers can use
224	// errors.As to inspect the HTTP status, or IsHTTPErrorStatus for a quick check.
225	type HTTPError struct {
226		StatusCode int
227		Message    string
228	}
229	
230	func (e *HTTPError) Error() string {
231		if e.Message != "" {
232			return fmt.Sprintf("API error: %s (status %d)", e.Message, e.StatusCode)
233		}
234		return fmt.Sprintf("API error: status %d", e.StatusCode)
235	}
236	
237	// IsHTTPErrorStatus reports whether err wraps an *HTTPError with the given HTTP status.
238	func IsHTTPErrorStatus(err error, status int) bool {
239		var ae *HTTPError
240		return errors.As(err, &ae) && ae.StatusCode == status
241	}
242	
243	// CheckResponse returns an error if the response status code indicates failure.
244	// For non-2xx responses, it reads and parses the error message from the body
245	// and returns it as an *HTTPError. The caller is responsible for closing resp.Body.
246	func CheckResponse(resp *http.Response) error {
247		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
248			return nil
249		}
250	
251		apiError := &HTTPError{StatusCode: resp.StatusCode}
252	
253		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
254		if err != nil {
255			return apiError
256		}
257	
258		var parsed ErrorResponse
259		if err := json.Unmarshal(body, &parsed); err == nil {
260			if message := parsed.Message(); message != "" {
261				apiError.Message = message
262				return apiError
263			}
264		}
265	
266		if text := strings.TrimSpace(string(body)); text != "" {
267			apiError.Message = text
268		}
269		return apiError
270	}
